const source = $input.first().json;
const value = String(source.ioc_value || source.value || source.domain || '').trim().toLowerCase().replace(/\.$/, '');
const domain = /^(?=.{1,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/;
const valid = domain.test(value);
const escaped = value.replace(/\\/g, '\\\\').replace(/"/g, '\\"');
return [{ json: {
  observable: { type: 'domain', value: valid ? value : null },
  valid_input: valid,
  validation_error: valid ? '' : 'Expected a valid fully-qualified domain name.',
  splunk_query: valid ? `index=wazuh (data.win.eventdata.queryName="${escaped}" OR data.win.eventdata.dnsQuery="${escaped}" OR dns_query="${escaped}") earliest=-24h latest=now | head 20` : ''
} }];

const input = $('Validate Domain Observable').item.json;
const splunk = $('Splunk Domain Context').item.json || {};
const misp = $input.item.json || {};
const errorText = (value) => String(value?.message || value || '').slice(0, 400);
const splunkStatus = splunk.error ? 'error' : 'ok';
const mispStatus = misp.error ? 'error' : 'ok';
const rows = Array.isArray(splunk.rows) ? splunk.rows : [];
const results = Array.isArray(splunk.result) ? splunk.result : (splunk.result ? [splunk.result] : rows);
const attrs = misp?.response?.Attribute || misp?.Attribute || [];
const matches = Array.isArray(attrs) ? attrs.slice(0, 5).map(a => ({ type:a.type||null, value:a.value||null, category:a.category||null, event:a.Event?.info||null, threat_level:a.Event?.threat_level_id||null })) : [];
const rawMatches = Array.isArray(attrs) ? attrs.slice(0, 5) : [];
const isInternalControlledObservation = (a) => {
  const eventInfo = String(a?.Event?.info || '');
  const toIds = String(a?.to_ids ?? '').toLowerCase();
  return /^SOC Lab - Controlled Internal Observation -/.test(eventInfo) &&
    (toIds === '' || toIds === '0' || toIds === 'false');
};
const internalObservationMatches = rawMatches.filter(isInternalControlledObservation);
const externalIocMatches = rawMatches.filter(a => !isInternalControlledObservation(a));
return [{ json: { observable: input.observable, enrichment: {
  status: splunkStatus === 'error' || mispStatus === 'error' ? 'degraded' : 'ok',
  splunk_status:splunkStatus, splunk_error:splunkStatus === 'error' ? errorText(splunk.error) : '',
  splunk_events_found:results.length, splunk_summary:results.slice(0,10),
  misp_status:mispStatus, misp_error:mispStatus === 'error' ? errorText(misp.error) : '',
  misp_hits_found:matches.length, misp_matches:matches, misp_internal_observation_matches: internalObservationMatches.length,
    misp_has_internal_observation: internalObservationMatches.length > 0,
    misp_external_ioc_matches: externalIocMatches.length,
    misp_is_known_ioc: externalIocMatches.length > 0,
  enrichment_degraded:splunkStatus === 'error' || mispStatus === 'error'
} } }];
